1	export interface Customer {
2	  yearsWithMHPCO: number;
3	}
4	
5	export interface Item {
6	  type: string;
7	  material?: string;
8	  enchantment?: number;
9	  cursed?: boolean;
10	}
11	
12	export interface QuoteStep {
13	  op: "quote";
14	  items: Item[];
15	}
16	
17	export interface Damage {
18	  itemType: string;
19	  amount: number;
20	}
21	
22	export interface ClaimStep {
23	  op: "claim";
24	  policy: number;
25	  incident: { cause: string; damages: Damage[] };
26	}
27	
28	export type Step = QuoteStep | ClaimStep;
29	
30	export interface Scenario {
31	  customer: Customer;
32	  steps: Step[];
33	}
34	
35	export type StepResult =
36	  | { premium: number }
37	  | { payout: number; remainingCap: number };
38	
39	export interface ScenarioResult {
40	  results: StepResult[];
41	}
42	
43	/**
44	 * Added at the very end of every premium, after all percentage modifiers, so
45	 * no surcharge or discount is ever computed on top of it.
46	 */
47	const PROCESSING_FEE = 5;
48	
49	/**
50	 * Rates are kept as exact numerator/denominator fractions rather than float
51	 * multipliers (10 / 100, never 1.1) so intermediate amounts stay exact and
52	 * only the final premium is rounded.
53	 */
54	const percent = (amount: number, rate: number): number => (amount * rate) / 100;
55	
56	const FIRST_INSURANCE_SURCHARGE_PERCENT = 10;
57	const CURSE_SURCHARGE_PERCENT = 50;
58	const HIGH_ENCHANTMENT_SURCHARGE_PERCENT = 30;
59	const HIGH_ENCHANTMENT_THRESHOLD = 5;
60	const LOYALTY_DISCOUNT_PERCENT = 20;
61	const LOYALTY_THRESHOLD_YEARS = 2;
62	const FOLLOW_UP_DISCOUNT_PERCENT = 15;
63	
64	/**
65	 * Everything the pricing rules need to know about an item type lives here, so
66	 * that "what is a rune?" has a single answer. Components are the small parts
67	 * (runes, moonstones) that can be bought as a building block; main items
68	 * (swords, amulets, ...) never form a block.
69	 */
70	const ITEM_TYPES: Record<
71	  string,
72	  { unitPremium: number; insuranceValue: number; isComponent: boolean }
73	> = {
74	  sword: { unitPremium: 100, insuranceValue: 1000, isComponent: false },
75	  amulet: { unitPremium: 60, insuranceValue: 600, isComponent: false },
76	  staff: { unitPremium: 80, insuranceValue: 800, isComponent: false },
77	  potion: { unitPremium: 40, insuranceValue: 400, isComponent: false },
78	  rune: { unitPremium: 25, insuranceValue: 250, isComponent: true },
79	  moonstone: { unitPremium: 25, insuranceValue: 250, isComponent: true },
80	};
81	
82	/** A building block of 3 alike components is offered at this base premium. */
83	const COMPONENT_BLOCK_BASE_PREMIUM = 60;
84	const COMPONENT_BLOCK_SIZE = 3;
85	
86	/** Tallies how many items of each type a policy covers, e.g. [["rune", 3]]. */
87	const countByType = (items: Item[]): [string, number][] => {
88	  const counts = new Map<string, number>();
89	  for (const item of items) {
90	    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
91	  }
92	  return [...counts];
93	};
94	
95	/**
96	 * Prices every item of one type together, because exactly 3 alike components
97	 * form a block charged as one. "Alike" means the same type, and the block does
98	 * not repeat: 4 or 7 runes are each priced per item.
99	 */
100	const basePremiumForType = (type: string, count: number): number => {
101	  const { unitPremium, isComponent } = ITEM_TYPES[type];
102	  return isComponent && count === COMPONENT_BLOCK_SIZE
103	    ? COMPONENT_BLOCK_BASE_PREMIUM
104	    : count * unitPremium;
105	};
106	
107	const sumOfBasePremiums = (items: Item[]): number =>
108	  countByType(items).reduce(
109	    (sum, [type, count]) => sum + basePremiumForType(type, count),
110	    0,
111	  );
112	
113	/**
114	 * Item-specific modifiers: each applies to one item and is charged as a
115	 * percentage of THAT item's unit premium, never of the policy total.
116	 * They stack — an item matching several rules is charged for each.
117	 *
118	 * Unit premium, not the item's share of the policy base: the two differ only
119	 * for components inside a block of 3 (billed 60 G for three 25 G runes), and
120	 * no test pins down a surcharged component yet. Revisit when one does.
121	 */
122	const ITEM_MODIFIERS: { appliesTo: (item: Item) => boolean; rate: number }[] = [
123	  { appliesTo: (item) => item.cursed === true, rate: CURSE_SURCHARGE_PERCENT },
124	  {
125	    appliesTo: (item) => (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD,
126	    rate: HIGH_ENCHANTMENT_SURCHARGE_PERCENT,
127	  },
128	];
129	
130	const surchargeForItem = (item: Item): number =>
131	  ITEM_MODIFIERS.filter(({ appliesTo }) => appliesTo(item)).reduce(
132	    (sum, { rate }) => sum + percent(ITEM_TYPES[item.type].unitPremium, rate),
133	    0,
134	  );
135	
136	const sumOfItemSurcharges = (items: Item[]): number =>
137	  items.reduce((sum, item) => sum + surchargeForItem(item), 0);
138	
139	/**
140	 * Policy-wide modifiers: each is charged as a percentage of the POLICY BASE
141	 * premium (the sum of item base premiums, before any item surcharge), so no
142	 * modifier is ever computed on top of another. Discounts carry a negative rate.
143	 */
144	interface PolicyContext {
145	  customer: Customer;
146	  /** Quotes already issued to this customer earlier in the scenario. */
147	  previousContracts: number;
148	}
149	
150	const POLICY_MODIFIERS: {
151	  appliesTo: (context: PolicyContext) => boolean;
152	  rate: number;
153	}[] = [
154	  // Always applies: every item in a quote is treated as a first insurance,
155	  // regardless of how long the customer has been with the MHPCO.
156	  { appliesTo: () => true, rate: FIRST_INSURANCE_SURCHARGE_PERCENT },
157	  {
158	    // Negative rate: a discount is just a surcharge pointing the other way, so
159	    // it needs no separate code path and cannot stack onto another modifier.
160	    appliesTo: ({ customer }) =>
161	      customer.yearsWithMHPCO >= LOYALTY_THRESHOLD_YEARS,
162	    rate: -LOYALTY_DISCOUNT_PERCENT,
163	  },
164	  {
165	    appliesTo: ({ previousContracts }) => previousContracts >= 1,
166	    rate: -FOLLOW_UP_DISCOUNT_PERCENT,
167	  },
168	];
169	
170	const sumOfPolicyAdjustments = (
171	  context: PolicyContext,
172	  policyBasePremium: number,
173	): number =>
174	  POLICY_MODIFIERS.filter(({ appliesTo }) => appliesTo(context)).reduce(
175	    (sum, { rate }) => sum + percent(policyBasePremium, rate),
176	    0,
177	  );
178	
179	const premiumFor = (context: PolicyContext, items: Item[]): number => {
180	  const policyBasePremium = sumOfBasePremiums(items);
181	  return Math.ceil(
182	    policyBasePremium +
183	      sumOfItemSurcharges(items) +
184	      sumOfPolicyAdjustments(context, policyBasePremium) +
185	      PROCESSING_FEE,
186	  );
187	};
188	
189	/**
190	 * Steps are executed in order because a step's result can depend on the ones
191	 * before it: only the count of contracts already issued carries across steps so
192	 * far, but claims will later have to share a remaining cap the same way.
193	 */
194	/** A policy created by a quote step, tracked so later claims can draw on it. */
195	interface Policy {
196	  items: Item[];
197	  remainingCap: number;
198	}
199	
200	const DEDUCTIBLE_PER_DAMAGE = 100;
201	const CAP_MULTIPLE_OF_INSURANCE_SUM = 2;
202	
203	const insuranceSumOf = (items: Item[]): number =>
204	  items.reduce((sum, item) => sum + ITEM_TYPES[item.type].insuranceValue, 0);
205	
206	const payoutForDamage = (damage: Damage): number =>
207	  damage.amount - DEDUCTIBLE_PER_DAMAGE;
208	
209	export const runScenario = (scenario: Scenario): ScenarioResult => {
210	  let previousContracts = 0;
211	  const policies = new Map<number, Policy>();
212	
213	  const results = scenario.steps.map((step, index): StepResult => {
214	    if (step.op === "claim") {
215	      const policy = policies.get(step.policy) as Policy;
216	      const payout = step.incident.damages.reduce(
217	        (sum, damage) => sum + payoutForDamage(damage),
218	        0,
219	      );
220	      policy.remainingCap -= payout;
221	      return { payout, remainingCap: policy.remainingCap };
222	    }
223	
224	    const premium = premiumFor(
225	      { customer: scenario.customer, previousContracts },
226	      step.items,
227	    );
228	    policies.set(index, {
229	      items: step.items,
230	      remainingCap:
231	        CAP_MULTIPLE_OF_INSURANCE_SUM * insuranceSumOf(step.items),
232	    });
233	    // Counted after pricing, so a quote never discounts itself, and only for
234	    // quotes, because a claim does not issue a contract.
235	    previousContracts += 1;
236	    return { premium };
237	  });
238	  return { results };
239	};
