  damage.amount - DEDUCTIBLE_PER_DAMAGE;

export const runScenario = (scenario: Scenario): ScenarioResult => {
  let previousContracts = 0;
  const policies = new Map<number, Policy>();

  const results = scenario.steps.map((step, index): StepResult => {
    if (step.op === "claim") {
      const policy = policies.get(step.policy) as Policy;
      const payout = step.incident.damages.reduce(
        (sum, damage) => sum + payoutForDamage(damage),
